INSERT INTO preguntas (categoria, pregunta, opciones, respuesta, explicacion, activa) VALUES
  ('Movilidad', '¿DE LAS SIGUIENTES AFIRMACIONES SOBRE MOVILIDAD CUAL ES CORRECTA?', '["MOVILIDAD SALUDABLE COMO UN PROPÓSITO DEL SECTOR SALUD. MOVERSE MÁS VECES, MÁS TIEMPO, SIN DEPENDENCIA DE MEDIOS MOTORIZADOS Y CON ACCESIBILIDAD PARA TODOS", "MOVILIDAD SEGURA, ES UN MEDIO PARA MANTENER Y PROMOVERLA SALUD. EN DONDE LAS PERSONAS SE MUEVEN COTIDIANAMENTE SIN GENERAR RIESGOS NI EXPOSICIÓN A AMENAZAS CONTRA LA VIDA Y LA SALUD", "MOVILIDAD SOSTENIBLE, ES UN MODO QUE BUSCA ARTICULAR ACTORES Y SECTORES DE MANERA RACIONAL, EQUITATIVA Y FUNCIONAL EN LA PRESERVACIÓN DE LA CALIDAD DEL AIRE Y DEL AMBIENTE NATURAL Y ANTRÓPICO CON ACCIONES A NIVEL AMBIENTAL, ECONÓMICO, POLÍTICO Y SOCIAL", "TODAS LAS ANTERIORES SON CORRECTAS"]'::jsonb, 3, 'La respuesta correcta es: TODAS LAS ANTERIORES SON CORRECTAS.', true),
  ('Señales', '¿QUE ES VELOCIDAD INADECUADA?', '["NO DETENERSE ANTE ALGUN OBSTÁCULO QUE SURJA EN LA CONDUCCIÓN", "NO RESPETAR LAS SEÑALES QUE LIMITAN LA VELOCIDAD", "VELOCIDAD NO ADAPTADA A LAS CONDICIONES DE LA VÍA, DEL TRÁFICO, DEL VEHÍCULO O DEL PROPIO CONDUCTOR", "TODAS LAS ANTERIORES CON CORRECTAS"]'::jsonb, 3, 'La respuesta correcta es: TODAS LAS ANTERIORES CON CORRECTAS.', true),
  ('Conducción Segura', '¿LA VELOCIDAD INFLUYE EN EL CAMPO VISUAL DEL CONDUCTOR?', '["NO, ES IGUAL LA VISIÓN A CUALQUIER VELOCIDAD", "SI, A MENOR VELOCIDAD MENOS VISIÓN", "NO, A MAYOR VELOCIDAD MÁS VISIÓN", "SI, EL CAMPO VISUAL DISMINUYE AL AUMENTAR LA VELOCIDAD"]'::jsonb, 3, 'La respuesta correcta es: SI, EL CAMPO VISUAL DISMINUYE AL AUMENTAR LA VELOCIDAD.', true),
  ('Primeros Auxilios', '¿IDENTIFIQUE CUALES SON LOS ACTORES MÁS VULNERABLES DADO AL NIVEL DE GRAVEDAD DE SUS LESIONES EN CASO DE UN SINIESTRO VIAL?', '["EL PEATÓN, USUARIO BICICLETA Y USUARIO MOTOCICLETA", "LOS PASAJEROS DE UN BUS", "SOLO LOS PEATONES", "LOS USUARIOS DE BICICLETA"]'::jsonb, 0, 'La respuesta correcta es: EL PEATÓN, USUARIO BICICLETA Y USUARIO MOTOCICLETA.', true),
  ('Motociclistas', 'CUÁLES DE LOS SIGUIENTES MEDIOS DE TRANSPORTE HACEN PARTE DEL TRANSPORTE ACTIVO Y SOSTENIBLE?', '["A PIE Y EN BICICLETA", "A PIE, BICICLETAS, PATINES. MONOPATINES Y PATINETAS", "A Y B SON CORRECTAS", "EN VEHÍCULO PARTICULAR Y MOTOCICLETAS"]'::jsonb, 2, 'La respuesta correcta es: A Y B SON CORRECTAS.', true),
  ('General', 'SE PUEDE REALIZAR EL CAMBIO DE UBICACIÓN DE LA PLACA EN UN VEHICULO AL RECOMENDADO', '["NO, LA PLACA DEBE IR EN EL LUGAR ESTABLECIDO QUE VIENE DE FABRICA", "SI, LO IMPORTANTE ES QUE LA PLACA TENGA VISIBILIDAD DESDE LA PARTE DE ATRÁS", "SÍ, PERO SE DEBE SACAR UN PERMISO PARA PODER REALIZAR ESTE CAMBIO DE UBICACIÓN", "NINGUNA DE LAS ANTERIORES"]'::jsonb, 1, 'La respuesta correcta es: SI, LO IMPORTANTE ES QUE LA PLACA TENGA VISIBILIDAD DESDE LA PARTE DE ATRÁS.', true),
  ('Conducción Segura', '¿QUE SE ENTIENDE POR CONDUCIR A LA DEFENSIVA?', '["HACER VALER SUS DERECHOS EN TODO MOMENTO", "FRENAR ANTES DE CADA CRUCE", "TOMAR EN CUENTA LOS POSIBLES ERRORES DE LOS DEMÁS", "CULPAR A LOS DEMÁS POR SUS ERRORES AL CONDUCIR"]'::jsonb, 2, 'La respuesta correcta es: TOMAR EN CUENTA LOS POSIBLES ERRORES DE LOS DEMÁS.', true),
  ('General', 'LA CONDUCCIÓN PREVENTIVA SE BASA EN 3 PRINCIPIOS BÁSICOS QUE SON:', '["VISIÓN Y GESTIÓN DEL ESPACIO", "VISIÓN, ANTICIPACIÓN Y GESTIÓN DEL TIEMPO", "VISIÓN, ANTICIPACIÓN Y GESTIÓN DEL ESPACIO", "NINGUNA DE LAS ANTERIORES"]'::jsonb, 2, 'La respuesta correcta es: VISIÓN, ANTICIPACIÓN Y GESTIÓN DEL ESPACIO.', true),
  ('Mecánica', 'PARA CONDUCIR DE MANERA EFICIENTE SE DEBE:', '["ACELERAR EL VEHÍCULO A LAS REVOLUCIONES NECESARIAS PARA PREVENIR POSIBLES DAÑOS DEL MOTOR EL AHORRO DE COMBUSTIBLE Y LA NO CONTAMINACION AMBIENTAL", "ACELERAR EL VEHÍCULO A LAS MÁXIMAS REVOLUCIONES PARA PODER TENER UN ARRANQUE QUE SEA RÁPIDO Y EFICAZ", "TRATAR DE ARRANCAR EL VEHÍCULO SOLAMENTE CON EL PUNTO DE CONTACTO SIN HACER EL USO DE LAS REVOLUCIONES", "NINGUNA DE LAS ANTERIORES"]'::jsonb, 0, 'La respuesta correcta es: ACELERAR EL VEHÍCULO A LAS REVOLUCIONES NECESARIAS PARA PREVENIR POSIBLES DAÑOS DEL MOTOR EL AHORRO DE COMBUSTIBLE Y LA NO CONTAMINACION AMBIENTAL.', true),
  ('Infracciones', 'QUE SANCIÓN DE MULTA SERÁ IMPUESTA AL CONDUCTOR DE UN VEHICULO POR ESTACIONAR EL VEHÍCULO EN SITIOS PROHIBIDOS?', '["4 SMDLV", "15 SMDLV", "8 SMDLV", "30 SMDLV"]'::jsonb, 1, 'La respuesta correcta es: 15 SMDLV.', true),
  ('Documentos', 'CUANTO ES EL VALOR DE LA INFRACCION DE CONDUCIR UN VEHICULO SIN LLEVAR CONSIGO LA LICENCIA DE CONDUCCIÓN', '["15 SMLDV", "8 SMLDV", "2 SMLDV", "12 SMLDV"]'::jsonb, 1, 'La respuesta correcta es: 8 SMLDV.', true),
  ('Mecánica', 'QUE SIGNIFICA EL SISTEMA ABS EN UN VEHICULO', '["SISTEMA DE RETENCIÓN INFANTIL", "SISTEMA DE FRENOS ANTIBLOQUEO", "SISTEMA DE ACELERACIÓN", "NINGUNA DE LAS ANTERIORES"]'::jsonb, 1, 'La respuesta correcta es: SISTEMA DE FRENOS ANTIBLOQUEO.', true),
  ('Señales', '¿DE LOS SIGUIENTES COMPORTAMIENTOS CUAL VULNERA MÁS LA CONDICIÓN DE ACTORES VIALES?', '["IGNORAR LAS SEÑALES DE TRÁNSITO", "PASAR LOS SEMÁFOROS EN ROJO", "GIRAR SIN MIRAR ATRÁS NI HACER SEÑALES MANUALES. USAR LOS CASCOS SIN ABROCHAR Y ZIGZAGUEAR ENTRE VEHÍCULOS", "TODAS LAS ANTERIORES"]'::jsonb, 3, 'La respuesta correcta es: TODAS LAS ANTERIORES.', true),
  ('Motociclistas', '14 CUÁL ES EL ACTOR MÁS VULNERABLE EN LA VÍA POR LO TANTO REQUIERE DE ESPECIAL PROTECCIÓN?', '["MOTOCICLISTA", "PEATONES", "CONDUCTOR DE MOTOCICLETA", "CONDUCTOR DE VEHÍCULOS"]'::jsonb, 1, 'La respuesta correcta es: PEATONES.', true),
  ('Conducción Segura', '¿CUÁL ES LA VELOCIDAD MÁXIMA PERMITIDA EN ZONAS ESCOLARES Y RESIDENCIALES EN LAS VÍAS RURALES?', '["30KM/H", "60KM/H", "20KM/H", "90KRN/H"]'::jsonb, 0, 'La respuesta correcta es: 30KM/H.', true),
  ('Documentos', '¿CUANDO HABLAMOS DE AUTORREGULACIÓN NOS REFERIMOS A?', '["PASAR EL SEMÁFORO EN LUZ AMARILLA", "CONDUCIR UN VEHÍCULO SIN TENER LA LICENCIA DE CONDUCCIÓN", "COMPRENDER LA IMPORTANCIA DE ACATAR LAS NORMAS DE TRÁNSITO DE FORMA AUTÓNOMA PARA NO PONER EN RIESGO SU VIDA Y LA DE LOS DEMAS", "TODAS LAS ANTERIORES"]'::jsonb, 2, 'La respuesta correcta es: COMPRENDER LA IMPORTANCIA DE ACATAR LAS NORMAS DE TRÁNSITO DE FORMA AUTÓNOMA PARA NO PONER EN RIESGO SU VIDA Y LA DE LOS DEMAS.', true),
  ('Autoridades y Normas', 'A HABLAR DE AUTORIDADES DE TRANSITO NOS REFERIMOS A:', '["POLICIA", "SECRETARIA DE EDUCACIÓN", "AGENTES DE TRÁNSITO Y POLICÍA DE TRANSITO", "TODAS ANTERIORES"]'::jsonb, 2, 'La respuesta correcta es: AGENTES DE TRÁNSITO Y POLICÍA DE TRANSITO.', true),
  ('Documentos', 'QUE DOCUMENTOS SE DEBE PRESENTAR A UNA AUTORIDAD DE TRANSITO?', '["LICENCIA DE CONDUCCIÓN Y CEDULA DE CIUDADANÍA", "SOAT Y REVISIÓN TECNOMECÁNICA", "LICENCIA DE TRANSITO", "TODAS LAS ANTERIORES"]'::jsonb, 3, 'La respuesta correcta es: TODAS LAS ANTERIORES.', true),
  ('Motociclistas', 'CUANTO ES EL VALOR DEL COMPARENDO POR NO PORTAR EL CASCO REGLAMENTARIO EN LA MOTOCICLETA.', '["8 SMDLV", "15 SMDLV", "30 SMDLV", "45 SMDLV"]'::jsonb, 1, 'La respuesta correcta es: 15 SMDLV.', true),
  ('Autoridades y Normas', 'EN LOS ASPECTOS LEGALES QUE LEY RIGE A LOS CONDUCTORES EN COLOMBIA', '["LEY 769 DEL 2002", "LEY 1801 DEL 2016", "CONSTITUCIÓN POLÍTICA 1991", "LEY 1122 DEL 2007"]'::jsonb, 0, 'La respuesta correcta es: LEY 769 DEL 2002.', true),
  ('Movilidad', '21 QUIEN SE ENCARGA DE EXPEDIR LOS DECRETOS Y RESTRICCIONES ESPECIFICAS EN LA MOVILIDAD DE TU CIUDAD?', '["EL MINISTERIO DEL INTERIOR", "LA SECRETARIA DE EDUCACIÓN", "SECRETARIA DE TRANSITO", "EL ALCALDE"]'::jsonb, 3, 'La respuesta correcta es: EL ALCALDE.', true),
  ('Peatones y Ciclistas', 'DE LOS SIGUIENTES ENUNCIADOS CUAL ES CONSIDERADA COMO UNA CONDUCTA INAPROPIADA EN LA VIA.', '["DETENER EL VEHICULO ANTES DE LA LÍNEA DE PASO PEATONAL", "CEDER EL PASO", "RESPETAR LOS LÍMITES DE VELOCIDAD", "SUBIR O ESTACIONAR LAS MOTOS EN LOS ANDENES DE LAS CASAS"]'::jsonb, 3, 'La respuesta correcta es: SUBIR O ESTACIONAR LAS MOTOS EN LOS ANDENES DE LAS CASAS.', true),
  ('General', 'CUÁL ES LA EMOCIÓN QUE DEBO CONTROLAR EN UNA CONGESTIÓN VEHICULAR SI VOY TARDE PARA UNA CITA.', '["LA IRA", "EL RESPETO", "LA TOLERANCIA", "TODAS LAS ANTERIORES"]'::jsonb, 3, 'La respuesta correcta es: TODAS LAS ANTERIORES.', true),
  ('Primeros Auxilios', 'POR QUÉ NO DEBO CONDUCIR BAJO EL EFECTO DEL ALCOHOL', '["POR QUÉ VOY MÁS LENTO", "POR QUÉ VOY FELIZ", "POR QUÉ PUEDO CAUSAR UN ACCIDENTE", "PORQUE AUMENTA MI CAPACIDAD DE REACCIÓN"]'::jsonb, 2, 'La respuesta correcta es: POR QUÉ PUEDO CAUSAR UN ACCIDENTE.', true),
  ('Conducción Segura', 'CUAL ES LA VELOCIDAD MÁXIMA PERMITIDA EN COLOMBIA EN EL PERIMETRO RURAL', '["60 KM/H", "80 KM/H", "120 KM/H", "100 KM/H"]'::jsonb, 1, 'La respuesta correcta es: 80 KM/H.', true),
  ('Señales', 'QUE SIGNIFICA LA SIGUIENTE SEÑAL', '["ZONA DE DISCAPACITADOS", "PARE", "ZONA DE SILLA DE RUEDAS", "NINGUNA DE LAS ANTERIORES"]'::jsonb, 0, 'La respuesta correcta es: ZONA DE DISCAPACITADOS.', true),
  ('Señales', 'USTED LLEGA A UNA INTERSECCIÓN REGULADA POR UN SEMÁFORO QUE SE ENCUENTRA EN ROJO, AL MISMO TIEMPO, UN POLICÍA O AGENTE DE TRÁNSITO LE INDICA QUE AVANCE. ¿QUÉ DEBE HACER USTED?', '["DETENERSE PORQUE LA LUZ ROJA LO INDICA", "AVANZAR, PORQUE LAS INSTRUCCIONES DE UN AGENTE, PREVALECEN SOBRE LAS SEÑALES DE TRÁNSITO", "AVANZAR, SOLO SI DETRÁS SUYO NO VIENE OTROS VEHÍCULOS", "AVANZAR, SOLO SI ESTÁ SEGURO QUE LA LUZ ROJA VA A CAMBIAR"]'::jsonb, 1, 'La respuesta correcta es: AVANZAR, PORQUE LAS INSTRUCCIONES DE UN AGENTE, PREVALECEN SOBRE LAS SEÑALES DE TRÁNSITO.', true),
  ('General', 'QUE ES UNA VÍA', '["ESPACIO DESTINADO AL PASO DE VEHÍCULOS O PERSONAS QUE VAN DE UN LUGAR A OTRO", "LUGAR POR DONDE SE CIRCULA O DESPLAZA", "INFRAESTRUCTURA QUE PERMITE LA CIRCULACIÓN EN CONDICIONES DE SEGURIDAD A LOS ACTORES VIALES", "TODAS LAS ANTERIORES"]'::jsonb, 3, 'La respuesta correcta es: TODAS LAS ANTERIORES.', true),
  ('Alcohol y Sustancias', 'LA PERSONA QUE SE ENCUENTRE CONDUCIENDO BAJO LOS EFECTOS DEL ALCOHOL EN TERCER GRADO SERÁ SANCIONADO DE LA SIGUIENTE MANERA', '["720 SMLDV Y SUSPENSIÓN DÉ LA LICENCIA DE CONDUCCIÓN DURANTE DIEZ (10) AÑOS", "180 SMLDV Y SUSPENSIÓN DE LA LICENCIA DE CONDUCCIÓN QUINCE AÑOS(15) AÑOS", "90 SMLDV Y SUSPENSIÓN DE LA LICENCIA DE CONDUCCIÓN DURANTE DOS (2) AÑOS", "360 SMLDV Y SUSPENSIÓN DE LA LICENCIA DE CONDUCCIÓN DURANTE SEIS (6) AÑOS"]'::jsonb, 0, 'La respuesta correcta es: 720 SMLDV Y SUSPENSIÓN DÉ LA LICENCIA DE CONDUCCIÓN DURANTE DIEZ (10) AÑOS.', true),
  ('Primeros Auxilios', '¿CUÁL DE LAS SIGUIENTES AFIRMACIONES SON VERDADERAS?', '["EL CONDUCTOR IMPRUDENTE, CONDUCE A ALTAS VELOCIDADES", "EL CONDUCTOR IMPRUDENTE, CREA SITUACIONES DE RIESGO CON ALTA FRECUENCIA", "CON FRECUENCIA LOS JÓVENES, CONDUCEN A ALTAS VELOCIDADES Y SE VEN MAS INVOLUCRADOS EN ACCIDENTES DE TRANSITO", "TODAS LAS ANTERIORES"]'::jsonb, 3, 'La respuesta correcta es: TODAS LAS ANTERIORES.', true),
  ('General', 'ENTRE EL ACELERADOR Y EL EMBRAGUE CUAL ES EL ENCARGADO DE DARLE EL MOVIMIENTO AL VEHÍCULO', '["EL ACELERADOR", "EL EMBRAGUE", "AMBOS DAN EL MOVIMIENTO", "NINGUNO DE ESTOS"]'::jsonb, 2, 'La respuesta correcta es: AMBOS DAN EL MOVIMIENTO.', true),
  ('Infracciones', 'QUE SANCIÓN SERÁ IMPUESTA AL CONDUCTOR POR PARQUEAR EN SITIOS PROHIBIDOS.', '["8 SMDLV", "15 SMDLV", "30 SMDLV", "45 SMDLV"]'::jsonb, 1, 'La respuesta correcta es: 15 SMDLV.', true),
  ('Señales', 'CUALES SON LAS SEÑALES QUE TIENE MAYOR PRELACIÓN?', '["SEÑALES Y ORDENES EMITIDAS POR UN AGENTE DE TRANSITO", "SEÑALES TRANSITORIAS Y SEMÁFOROS", "SEÑALES VERTICALES Y SEÑALES HORIZONTALES", "TODAS LAS ANTERIORES"]'::jsonb, 0, 'La respuesta correcta es: SEÑALES Y ORDENES EMITIDAS POR UN AGENTE DE TRANSITO.', true),
  ('General', 'UN CARRIL EXCLUSIVO ES:', '["DONDE VAN MOTOS Y CARROS", "UN CICLO RUTA", "UNA AVENIDA", "TRÁNSITO DE UNA SOLA CLASE DE VEHÍCULOS"]'::jsonb, 3, 'La respuesta correcta es: TRÁNSITO DE UNA SOLA CLASE DE VEHÍCULOS.', true),
  ('Peatones y Ciclistas', 'QUE ES UNA CICLO RUTA?', '["COMPLETAMENTE DE BICICLETA Y PEATONES", "VIA EXCLUSIVA PARA EL TRÁNSITO DE BICICLETA", "SESIÓN DE LA CALZADA DESTINA OCASIONALMENTE A ESPARCIMIENTO DE DEPORTE", "NINGUNA DE LAS ANTERIORES"]'::jsonb, 1, 'La respuesta correcta es: VIA EXCLUSIVA PARA EL TRÁNSITO DE BICICLETA.', true),
  ('Señales', 'SI QUIERO GIRAR A LA DERECHA EN UN SEMÁFORO CON FLECHA VERDE ILUMINADA. ¿SE TIENE PREFERENCIA DE PASO?', '["NO TENGO PREFERENCIA PORQUE LA LUZ ROJA PROHÍBE GIRAR", "NO TENGO PREFERENCIA, PERO LA LUZ VERDE ME PERMITE GIRAR SIEMPRE Y CUANDO TOME LAS DEBIDAS PRECAUCIONES", "SI TENGO PREFERENCIA PORQUE LA FLECHA ME LO PERMITE", "NINGUNA DE LAS ANTERIORES"]'::jsonb, 2, 'La respuesta correcta es: SI TENGO PREFERENCIA PORQUE LA FLECHA ME LO PERMITE.', true),
  ('General', 'LOS SISTEMAS DE SEGURIDAD PASIVA, ¿INCLUYEN LOS CINTURONES DE SEGURIDAD, AIRBAG, APOYACABEZAS Y CASCOS?', '["NO", "SI", "SÍ, PERO SIN LOS CASCOS", "NINGUNA DE LAS ANTERIORES"]'::jsonb, 1, 'La respuesta correcta es: SI.', true),
  ('Primeros Auxilios', '¿CUÁL ES LA FUNCIÓN DE LOS SISTEMAS DE SEGURIDAD PASIVA?', '["AMINORAR LOS DAÑOS CAUSADOS POR UN ACCIDENTE A LAS PERSONAS", "EVITAR QUE SE PRODUZCA UN ACCIDENTE", "AMINORAR LOS DAÑOS CAUSADOS POR UN ACCIDENTE A LOS VEHÍCULOS", "TODAS LAS ANTERIORES"]'::jsonb, 0, 'La respuesta correcta es: AMINORAR LOS DAÑOS CAUSADOS POR UN ACCIDENTE A LAS PERSONAS.', true),
  ('Mecánica', 'EL DISPOSITIVO QUE TRANSMITE LA ENERGÍA DEL MOTOR A LAS RUEDAS MOTRICES SE LLAMA:', '["TRANSMISIÓN", "DIRECCIÓN", "FRENO", "EMBRAGUE"]'::jsonb, 0, 'La respuesta correcta es: TRANSMISIÓN.', true),
  ('General', '¿QUÉ SIGNIFICA LA SIGLA EPP?', '["ELEMENTOS PARA LA PROTECCIÓN", "ESTADO DE PROTECCIÓN PERSONAL", "ELEMENTOS DE PROTECCIÓN PERSONAL", "ESTACIONAMIENTO PREVENTIVO PERSONAL"]'::jsonb, 2, 'La respuesta correcta es: ELEMENTOS DE PROTECCIÓN PERSONAL.', true),
  ('Señales', 'QUE SEÑALES PERTENECEN AL GRUPO DE LAS SEÑALES VERTICALES', '["PREVENTIVAS, INFORMATIVAS Y HORIZONTALES", "PREVENTIVAS, REGLAMENTARIAS E INFORMATIVAS", "PREVENTIVAS, REGLAMENTARIAS Y VERTICALES", "PREVENTIVAS, INFORMATIVAS Y CONOS"]'::jsonb, 1, 'La respuesta correcta es: PREVENTIVAS, REGLAMENTARIAS E INFORMATIVAS.', true),
  ('Primeros Auxilios', '¿CUAL ES LA FUNCIÓN DE LOS ELEMENTOS DE LA SEGURIDAD PASIVA?', '["MINIMIZAR EL IMPACTO Y CONSECUENCIAS DEL MISMO", "MANTENER EL CONTROL DEL AUTOMOTOR", "AMORTIGUAR LOS POSIBLES DAÑOS OCURRIDOS EN UN ACCIDENTE DE TRANSITO", "A Y C SON VERDADERAS"]'::jsonb, 3, 'La respuesta correcta es: A Y C SON VERDADERAS.', true),
  ('General', 'LA INSPECCIÓN PRE-OPERACIONAL DIARIA DEL VEHÍCULO AUTOMOTOR, SE DEBE REALIZAR PARA:', '["DARSE CUENTA DE CUANTO KILOMETRAJE HACE DE UN PUNTO A UN PUNTO", "CERCIORARSE DE QUE EL AUTOMOTOR, ESTÁ EN PERFECTAS CONDICIONES", "SABER SI LA GARANTÍA DEL AUTOMOTOR ESTÁ VIGENTE", "NINGUNA DE LAS ANTERIORES"]'::jsonb, 1, 'La respuesta correcta es: CERCIORARSE DE QUE EL AUTOMOTOR, ESTÁ EN PERFECTAS CONDICIONES.', true),
  ('Primeros Auxilios', 'LOS ELEMENTOS QUE MINIMIZAN LAS LESIONES CERVICALES EN CASO DE UN ACCIDENTE DE TRÁNSITO SON:', '["SEGURIDAD ACTIVA", "SEGURIDAD PASIVA", "MANDOS SUPERIORES", "ELEMENTOS DE SEGURIDAD"]'::jsonb, 1, 'La respuesta correcta es: SEGURIDAD PASIVA.', true),
  ('Conducción Segura', 'CUANTOS SEGUNDOS DEBEN PASAR DESPUÉS DE DETERMINAR EL PUNTO DE REFERENCIA PARA TENER UNA DISTANCIA ADECUADA ENTRE SU VEHÍCULO Y QUE VA DELANTE:', '["CUATRO SEGUNDOS", "TRES SEGUNDOS", "SIETE SEGUNDOS", "DOS SEGUNDOS"]'::jsonb, 0, 'La respuesta correcta es: CUATRO SEGUNDOS.', true),
  ('Mecánica', 'QUE ES LO MÁS IMPORTANTE PARA EVITAR CHOCAR AL VEHÍCULO QUE VA ADELANTE', '["ASEGURARSE DE QUE SUS FRENOS SEAN EFICIENTES", "CONDUCIR A UNA VELOCIDAD CONSTANTE", "MANTENER UNA ADECUADA DISTANCIA DE SEPARACIÓN ENTRE LOS DOS VEHÍCULOS", "TENER NEUMÁTICOS (LLANTAS) EN MUY BUEN ESTADO"]'::jsonb, 2, 'La respuesta correcta es: MANTENER UNA ADECUADA DISTANCIA DE SEPARACIÓN ENTRE LOS DOS VEHÍCULOS.', true),
  ('General', 'EL ALTO CONSUMO DE COMBUSTIBLE SE DEBE A:', '["FALLAS EN EL SISTEMA DE DIRECCIÓN", "ACELERACIONES EXCESIVAS", "FRECUENTES FRENADAS", "B Y C SON CIERTAS"]'::jsonb, 1, 'La respuesta correcta es: ACELERACIONES EXCESIVAS.', true),
  ('Mecánica', 'PARA CONOCER EL NIVEL ADECUADO DEL ACEITE DE UN MOTOR, LA MEDIDA EN LA VARILLA DEBE ESTAR:', '["EN EL MÍNIMO", ". EN LA MITAD", "EN EL MÁXIMO", "POR ENCIMA DEL MÁXIMO"]'::jsonb, 2, 'La respuesta correcta es: EN EL MÁXIMO.', true),
  ('Mecánica', 'EL ACEITE DE UN AUTOMOTOR, SE DEBE REVISAR:', '["CON EL MOTOR ENCENDIDO", "CON EL MOTOR APAGADO", "CON EL VEHÍCULO LEVEMENTE INCLINADO", "NINGUNA DE LAS ANTERIORES"]'::jsonb, 1, 'La respuesta correcta es: CON EL MOTOR APAGADO.', true),
  ('Mecánica', 'LA INSPECCIÓN PREOPERACIONARIAL DIARIA DEL AUTOMOTOR, SE DEBE REALIZAR', '["SOLO CON EL MOTOR ENCENDIDO, EN TERRENO PLANO", "SOLO CON EL MOTOR APAGADO, EN TERRENO PLANO", "CON EL MOTOR APAGADO Y CON EL MOTOR ENCENDIDO EN TERRENO PLANO", "NINGUNA APLICA"]'::jsonb, 1, 'La respuesta correcta es: SOLO CON EL MOTOR APAGADO, EN TERRENO PLANO.', true),
  ('Mecánica', 'SI SE OBSERVA, DESGASTE EN LA PARTE EXTERNA DE UN NEUMÁTICO, ES PORQUE EL AUTOMOTOR TIENE UN PROBLEMAS DE:', '["FLEXIBILIDAD", "BALANCEO", "SUSPENSIÓN", "ALINEACIÓN"]'::jsonb, 3, 'La respuesta correcta es: ALINEACIÓN.', true),
